// Crystal's standard library as its API docs describe it, generated by
// tools/gen_crystal_vocab.py into crystal_lsp_stdlib.cpp. Plain data for
// mep's own Crystal language server: completion, hover, signature help
// and ancestor walks, without needing `crystal` at build or run time.
#pragma once

#include <cstddef>
#include <cstdint>

struct CrystalStdType {
  const char *name;       // full name: "String", "Array(T)", "Hash(K, V)", "IO::Memory"
  const char *kind;       // class struct module enum alias annotation
  const char *superclass; // full name, "" if none (modules, Object)
  const char *includes;   // directly included modules, comma-separated full names
  const char *extends;    // directly extended modules, comma-separated
  const char *ancestors;  // the whole ancestor chain, nearest first, comma-separated
                          // (all type references use the referenced type's own `name`,
                          // e.g. "Enumerable(T)"; a few undocumented internals don't resolve)
  const char *aliased;    // for kind "alias": the aliased type ("Slice(UInt8)"), else ""
  const char *doc;        // first paragraph of the doc comment (Markdown)
};

struct CrystalStdMethod {
  const char *owner; // full type name; "" for top-level defs and macros
  const char *name;
  const char *args; // "(index : Int, count : Int)", block arg and " forall T" kept; "" if none
  const char *ret;  // return type as documented, or ""
  uint8_t kind;     // 0 instance method (and top-level def), 1 class method/constructor, 2 macro
  const char *doc;  // first paragraph of the doc comment (Markdown)
};

struct CrystalStdConst {
  const char *owner; // full type name, "" for top level; enum members are their enum's consts
  const char *name;
  const char *value; // source expression as documented
  const char *doc;
};

const char *CrystalStdVersion(); // the Crystal version the table was generated from
// Sorted by name (byte order).
const CrystalStdType *CrystalStdTypes(size_t *count);
// Sorted by (owner, name), byte order; overloads adjacent, in docs order.
const CrystalStdMethod *CrystalStdMethods(size_t *count);
// Grouped by owner (byte order), declaration order within an owner.
const CrystalStdConst *CrystalStdConsts(size_t *count);
